const items = $input.all();
const fileListItems = $('Create File List').all();
const output = [];

function cleanText(text) {
  return String(text || '')
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function splitLongText(text, maxLength = 900) {
  const chunks = [];
  let remaining = cleanText(text);

  while (remaining.length > maxLength) {
    let splitIndex = remaining.lastIndexOf('\n', maxLength);

    if (splitIndex < 300) {
      splitIndex = remaining.lastIndexOf('. ', maxLength);
    }

    if (splitIndex < 300) {
      splitIndex = maxLength;
    }

    const part = remaining.slice(0, splitIndex).trim();

    if (part) {
      chunks.push(part);
    }

    remaining = remaining.slice(splitIndex).trim();
  }

  if (remaining) {
    chunks.push(remaining);
  }

  return chunks;
}

for (let itemIndex = 0; itemIndex < items.length; itemIndex++) {
  const item = items[itemIndex];

  const metadata =
    item.json?.document_id
      ? item.json
      : fileListItems[itemIndex]?.json;

  if (!metadata?.document_id) {
    throw new Error(`Document metadata not found for item index ${itemIndex}`);
  }

  // n8n runtime provides this.helpers even if the editor marks it.
  // @ts-ignore
  const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, 'data');

  const fileContent = cleanText(buffer.toString('utf8'));

  const documentId = metadata.document_id;
  const title = metadata.title;
  const category = metadata.category;

  const lines = fileContent.split('\n');

  const sections = [];
  let currentSectionTitle = null;
  let currentLines = [];

  for (const line of lines) {
    const sectionMatch = line.match(/^##\s+(.+)$/);

    if (sectionMatch) {
      if (currentSectionTitle && currentLines.length > 0) {
        sections.push({
          section_title: currentSectionTitle,
          content: cleanText(currentLines.join('\n'))
        });
      }

      currentSectionTitle = sectionMatch[1].trim();
      currentLines = [line];
    } else if (currentSectionTitle) {
      currentLines.push(line);
    }
  }

  if (currentSectionTitle && currentLines.length > 0) {
    sections.push({
      section_title: currentSectionTitle,
      content: cleanText(currentLines.join('\n'))
    });
  }

  if (sections.length === 0) {
    sections.push({
      section_title: 'Genel',
      content: fileContent
    });
  }

  let chunkIndex = 1;

  for (const section of sections) {
    const textParts = splitLongText(section.content);

    for (const part of textParts) {
      output.push({
        json: {
          document_id: documentId,
          title,
          category,
          section_title: section.section_title,
          chunk_index: chunkIndex,
          content: part
        }
      });

      chunkIndex++;
    }
  }
}

return output;

const chunkData = $('Create Chunks').item.json;

const embedding = $json.embeddings?.[0];

if (!embedding) {
  throw new Error('Embedding not found');
}

function sqlEscape(value) {
  return String(value ?? '').replace(/'/g, "''");
}

const embeddingVector = `[${embedding.join(',')}]`;

const insertQuery = `
INSERT INTO document_chunks (
  document_id,
  title,
  category,
  section_title,
  chunk_index,
  content,
  embedding
)
VALUES (
  '${sqlEscape(chunkData.document_id)}',
  '${sqlEscape(chunkData.title)}',
  '${sqlEscape(chunkData.category)}',
  '${sqlEscape(chunkData.section_title)}',
  ${Number(chunkData.chunk_index)},
  '${sqlEscape(chunkData.content)}',
  '${embeddingVector}'::vector
);
`;

return {
  json: {
    document_id: chunkData.document_id,
    title: chunkData.title,
    category: chunkData.category,
    section_title: chunkData.section_title,
    chunk_index: chunkData.chunk_index,
    insert_query: insertQuery
  }
};

